package app;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {

    public record OrderLine(String productCode, int quantity) {
    }

    public record PlaceOrderCommand(UUID customerId, List<OrderLine> lines) {
    }

    private final OrderRepository orderRepository;

    OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    @Transactional
    public Optional<UUID> placeOrder(PlaceOrderCommand command) {
        if (command == null || command.lines().isEmpty()) {
            return Optional.empty();
        }
        UUID orderId = UUID.randomUUID();
        orderRepository.save(orderId, command);
        return Optional.of(orderId);
    }
}

